function buildDigest({ body, query }) {
  if (!body || typeof body !== "object" || Array.isArray(body) || !Array.isArray(body.tweets))
    throw new Error("Xquik did not return a tweets array.");
  const more = body.has_next_page ?? body.has_more ?? false;
  if (typeof more !== "boolean") throw new Error("Xquik pagination flag must be boolean.");
  const cursor = body.next_cursor ?? "";
  if (typeof cursor !== "string") throw new Error("Xquik cursor must be text.");
  const tweets = body.tweets.map((tweet) => {
    if (!tweet || typeof tweet !== "object" || Array.isArray(tweet))
      throw new Error("Xquik returned an invalid tweet.");
    const sourceId = tweet.id ?? tweet.tweet_id ?? tweet.rest_id ?? "";
    if (typeof sourceId !== "string" && !Number.isSafeInteger(sourceId))
      throw new Error("Xquik tweet ID must be text or a safe integer.");
    const id = String(sourceId);
    const text = tweet.text ?? tweet.full_text ?? tweet.content ?? "";
    const url = tweet.url ?? (id ? "https://x.com/i/web/status/" + encodeURIComponent(id) : "");
    const sourceAuthor = tweet.author ?? tweet.user ?? {};
    const author = sourceAuthor.username ?? sourceAuthor.screen_name ?? sourceAuthor.name ?? "";
    const created_at =
      tweet.createdAt ?? tweet.created_at ?? tweet.created ?? tweet.timestamp ?? "";
    if ([text, url, author, created_at].some((value) => typeof value !== "string"))
      throw new Error("Xquik text, URL, author and timestamp must be strings.");
    const metrics =
      tweet.metrics ??
      Object.fromEntries(
        ["likeCount", "retweetCount", "replyCount", "quoteCount", "viewCount", "bookmarkCount"]
          .filter((name) => Object.hasOwn(tweet, name))
          .map((name) => [name, tweet[name]]),
      );
    if (!metrics || typeof metrics !== "object" || Array.isArray(metrics))
      throw new Error("Xquik metrics must be an object.");
    return { id, url, text, author, created_at, metrics };
  });
  const lines = tweets.length
    ? tweets.map(
        (tweet, index) =>
          index +
          1 +
          ". " +
          tweet.text +
          (tweet.author ? " by " + tweet.author : "") +
          (tweet.url ? "\n" + tweet.url : ""),
      )
    : ["No matching X posts found for this query."];
  return {
    query,
    results_count: tweets.length,
    has_more: more,
    next_cursor: cursor,
    tweets,
    digest: lines.join("\n\n"),
  };
}

return [
  {
    json: buildDigest({
      body: $input.first().json,
      query: $("Validate search settings").first().json.query,
    }),
  },
];

function prepareSearch({ query, limit }) {
  if (typeof query !== "string" || !query.trim() || query.length > 4096)
    throw new Error("query must contain 1–4096 characters.");
  if (!Number.isInteger(limit) || limit < 1 || limit > 10000)
    throw new Error("limit must be an integer from 1 to 10000.");
  return { query, limit };
}

return [{ json: prepareSearch($input.first().json) }];
